SELECT id, brand, cost, supplier_id, launch_date, ROUND(cost / SUM(cost) OVER (PARTITION BY brand), 3) AS cost_share, SUM(cost) OVER (PARTITION BY supplier_id ORDER BY launch_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_cost FROM products WHERE product_name LIKE 'Ru%' ORDER BY launch_date, id DESC
